import { createHmac, timingSafeEqual, Buffer } from 'crypto';

/**
 * Custom error thrown when the CryptoValidator service is accessed before initialization.
 */
export class InitializationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'InitializationError';
  }
}

/**
 * Custom error thrown when an operational error occurs during cryptographic processing.
 */
export class CryptographicOperationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CryptographicOperationError';
  }
}

/**
 * CryptoValidator service responsible for HMAC-SHA256 signing and verification.
 * Designed for high-throughput event processing with timing-safe verification.
 */
export class CryptoValidator {
  private static instance: CryptoValidator | null = null;
  private readonly secretKey: Buffer;

  private constructor(signingKey: string) {
    this.secretKey = Buffer.from(signingKey, 'utf8');
  }

  /**
   * Initializes the singleton instance of the CryptoValidator.
   * Should be called at system boot time.
   * 
   * @param signingKey The secret key used for HMAC signing.
   */
  public static initialize(signingKey: string): void {
    if (!signingKey || signingKey.length === 0) {
      throw new InitializationError('Signing key cannot be empty.');
    }
    if (!CryptoValidator.instance) {
      CryptoValidator.instance = new CryptoValidator(signingKey);
    }
  }

  /**
   * Returns the initialized singleton instance of the CryptoValidator.
   */
  public static getInstance(): CryptoValidator {
    if (!CryptoValidator.instance) {
      throw new InitializationError('CryptoValidator has not been initialized. Call initialize() first.');
    }
    return CryptoValidator.instance;
  }

  /**
   * Signs a data payload using HMAC-SHA256.
   * 
   * @param data The JSON-stringified payload to sign.
   * @returns A hex-encoded HMAC signature string.
   */
  public async sign(data: string): Promise<string> {
    try {
      const hmac = createHmac('sha256', this.secretKey);
      hmac.update(data);
      return hmac.digest('hex');
    } catch (err) {
      throw new CryptographicOperationError('Failed to sign the payload.');
    }
  }

  /**
   * Verifies the authenticity of a payload against a provided signature.
   * Uses timing-safe comparison to prevent side-channel attacks.
   * 
   * @param data The original JSON-stringified payload.
   * @param signature The hex-encoded signature to verify.
   * @returns True if the signature is valid, false otherwise.
   */
  public async verify(data: string, signature: string): Promise<boolean> {
    try {
      const hmac = createHmac('sha256', this.secretKey);
      hmac.update(data);
      const calculatedSignature = hmac.digest();
      const providedSignatureBuffer = Buffer.from(signature, 'hex');

      // Verify the buffers have the same length before comparison to ensure safety
      if (calculatedSignature.length !== providedSignatureBuffer.length) {
        return false;
      }

      return timingSafeEqual(calculatedSignature, providedSignatureBuffer);
    } catch (err) {
      // In case of error (e.g. invalid encoding), return false to signify verification failure
      return false;
    }
  }
}

/**
 * @fileoverview Authoritative public API for the fraud detection engine's domain model.
 * Consolidates factories, type definitions, and branded identifiers for the event pipeline.
 */

import {
  Transaction,
  TransactionInitiated,
  TransactionValidated,
  TransactionFlagged,
  Telemetry,
  isTransactionInitiated,
  isTransactionValidated,
  isTransactionFlagged,
} from './definitions/transaction.interface';
import {
  UserId,
  TransactionId,
  MerchantId,
  MonetaryAmount,
  asUserId,
  asTransactionId,
  asMerchantId,
  createMonetaryAmount,
} from './common/domain-types';
import { EventEnvelopeFactory, MessageEnvelope } from './messaging/event-envelope.messaging';

export {
  Transaction,
  TransactionInitiated,
  TransactionValidated,
  TransactionFlagged,
  Telemetry,
  MonetaryAmount,
  UserId,
  TransactionId,
  MerchantId,
  MessageEnvelope,
  isTransactionInitiated,
  isTransactionValidated,
  isTransactionFlagged,
  asUserId,
  asTransactionId,
  asMerchantId,
  createMonetaryAmount,
};

/**
 * Factory class for creating and signing domain transaction objects.
 * Acts as the secure ingress gate for the event-sourced processing pipeline.
 */
export class TransactionFactory {
  /**
   * Creates, validates, and signs a TransactionInitiated event.
   */
  public static async createTransactionInitiated(
    transactionId: TransactionId,
    userId: UserId,
    merchantId: MerchantId,
    amount: MonetaryAmount,
    telemetry: Telemetry
  ): Promise<MessageEnvelope<TransactionInitiated>> {
    const event: TransactionInitiated = Object.freeze({
      type: 'TransactionInitiated',
      transactionId,
      userId,
      merchantId,
      amount,
      telemetry,
      timestamp: BigInt(Date.now()),
      metadata: {
        schemaVersion: 1,
        createdAt: Date.now(),
        // Signature field is handled within the EventEnvelopeFactory.create() logic,
        // using the cryptographically verified signature.
        signature: 'INTERNAL_PENDING', 
      },
    });

    return await EventEnvelopeFactory.create(event);
  }

  /**
   * Creates, validates, and signs a TransactionValidated event.
   */
  public static async createTransactionValidated(
    transactionId: TransactionId,
    userId: UserId,
    merchantId: MerchantId,
    amount: MonetaryAmount,
    telemetry: Telemetry,
    validatorId: string
  ): Promise<MessageEnvelope<TransactionValidated>> {
    const event: TransactionValidated = Object.freeze({
      type: 'TransactionValidated',
      transactionId,
      userId,
      merchantId,
      amount,
      telemetry,
      validatorId,
      timestamp: BigInt(Date.now()),
      metadata: {
        schemaVersion: 1,
        createdAt: Date.now(),
        signature: 'INTERNAL_PENDING',
      },
    });

    return await EventEnvelopeFactory.create(event);
  }

  /**
   * Creates, validates, and signs a TransactionFlagged event.
   */
  public static async createTransactionFlagged(
    transactionId: TransactionId,
    userId: UserId,
    merchantId: MerchantId,
    amount: MonetaryAmount,
    telemetry: Telemetry,
    reason: string,
    riskScore: number
  ): Promise<MessageEnvelope<TransactionFlagged>> {
    const event: TransactionFlagged = Object.freeze({
      type: 'TransactionFlagged',
      transactionId,
      userId,
      merchantId,
      amount,
      telemetry,
      reason,
      riskScore,
      timestamp: BigInt(Date.now()),
      metadata: {
        schemaVersion: 1,
        createdAt: Date.now(),
        signature: 'INTERNAL_PENDING',
      },
    });

    return await EventEnvelopeFactory.create(event);
  }
}

import { CryptoManager } from '../utils/security/security_manager';

/**
 * Interface defining the strict configuration schema for the application.
 * All environment variables must be mapped here.
 */
export interface SystemConfiguration {
  readonly SIGNING_KEY: string;
  readonly ENCRYPTION_KEY: string;
  readonly PUBLIC_KEY_PEM: string;
  readonly PRIVATE_KEY_PEM: string;
  readonly REDIS_URL: string;
  readonly KAFKA_BROKER_LIST: string[];
  readonly ENVIRONMENT: 'development' | 'production' | 'test';
}

/**
 * Registry for managing application dependencies and service lifecycles.
 */
export class DependencyContainer {
  private static instance: DependencyContainer;
  private readonly config: SystemConfiguration;
  private cryptoManagerInitialized: boolean = false;

  private constructor(config: SystemConfiguration) {
    this.config = Object.freeze(config);
  }

  /**
   * Validates and initializes the system configuration.
   * Ensures all required environment variables are present.
   */
  public static initialize(env: NodeJS.ProcessEnv): DependencyContainer {
    const requiredKeys = [
      'SIGNING_KEY',
      'ENCRYPTION_KEY',
      'PUBLIC_KEY_PEM',
      'PRIVATE_KEY_PEM',
      'REDIS_URL',
      'KAFKA_BROKERS',
      'NODE_ENV',
    ];

    for (const key of requiredKeys) {
      if (!env[key]) {
        throw new Error(`Missing mandatory configuration variable: ${key}`);
      }
    }

    const config: SystemConfiguration = {
      SIGNING_KEY: env.SIGNING_KEY!,
      ENCRYPTION_KEY: env.ENCRYPTION_KEY!,
      PUBLIC_KEY_PEM: env.PUBLIC_KEY_PEM!.replace(/\\n/g, '\n'),
      PRIVATE_KEY_PEM: env.PRIVATE_KEY_PEM!.replace(/\\n/g, '\n'),
      REDIS_URL: env.REDIS_URL!,
      KAFKA_BROKER_LIST: env.KAFKA_BROKERS!.split(','),
      ENVIRONMENT: (env.NODE_ENV as 'development' | 'production' | 'test') || 'production',
    };

    if (!DependencyContainer.instance) {
      DependencyContainer.instance = new DependencyContainer(config);
    }

    return DependencyContainer.instance;
  }

  /**
   * Returns the singleton instance of the dependency container.
   */
  public static getInstance(): DependencyContainer {
    if (!DependencyContainer.instance) {
      throw new Error('DependencyContainer not initialized. Call initialize() first.');
    }
    return DependencyContainer.instance;
  }

  /**
   * Initializes core services such as the CryptoManager.
   */
  public boot(): void {
    if (this.cryptoManagerInitialized) {
      return;
    }

    CryptoManager.initialize(
      this.config.ENCRYPTION_KEY,
      this.config.PUBLIC_KEY_PEM,
      this.config.PRIVATE_KEY_PEM
    );

    this.cryptoManagerInitialized = true;
  }

  public getConfig(): SystemConfiguration {
    return this.config;
  }
}

/**
 * @fileoverview Event Envelope implementation for Kafka-based messaging.
 * Provides a secure, versioned, and type-safe wrapper for domain events.
 */

import { CryptoValidator } from '../security/crypto-validator.service';
import { Transaction } from '../definitions/transaction.interface';

/**
 * Custom error thrown when a security violation occurs during envelope processing.
 */
export class SecurityViolationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SecurityViolationError';
  }
}

/**
 * Metadata encapsulated within every message envelope.
 */
export interface EnvelopeMetadata {
  readonly schemaVersion: string;
  readonly createdAtNs: bigint;
  readonly provenanceTrace: string;
}

/**
 * Generic Message Envelope structure for Kafka events.
 */
export interface MessageEnvelope<T> {
  readonly metadata: EnvelopeMetadata;
  readonly payload: T;
  readonly signature: string;
}

/**
 * Factory class for creating and signing event envelopes.
 */
export class EventEnvelopeFactory {
  private static readonly SCHEMA_VERSION = 'v1.0';

  /**
   * Creates a signed MessageEnvelope for a given transaction event.
   * 
   * @param payload The domain event object.
   * @returns A signed MessageEnvelope.
   */
  public static async create<T extends Transaction>(payload: T): Promise<MessageEnvelope<T>> {
    const metadata: EnvelopeMetadata = {
      schemaVersion: this.SCHEMA_VERSION,
      createdAtNs: BigInt(process.hrtime.bigint()),
      provenanceTrace: `proc:${process.pid}`,
    };

    const envelopePayload = {
      metadata,
      payload,
    };

    const serializedData = JSON.stringify(envelopePayload);

    let signature: string;
    try {
      signature = await CryptoValidator.getInstance().sign(serializedData);
    } catch (err) {
      throw new SecurityViolationError(`Failed to sign envelope: ${err instanceof Error ? err.message : 'Unknown error'}`);
    }

    const envelope: MessageEnvelope<T> = {
      ...envelopePayload,
      signature,
    };

    return Object.freeze(envelope);
  }

  /**
   * Validates the integrity of an envelope by re-verifying the signature.
   * 
   * @param envelope The envelope to verify.
   * @returns True if valid, throws SecurityViolationError if invalid.
   */
  public static async verifyEnvelope<T extends Transaction>(envelope: MessageEnvelope<T>): Promise<boolean> {
    const { signature, ...dataToVerify } = envelope;

    const serializedData = JSON.stringify(dataToVerify);

    let isValid: boolean;
    try {
      isValid = await CryptoValidator.getInstance().verify(serializedData, signature);
    } catch (err) {
      throw new SecurityViolationError(`Error during verification process: ${err instanceof Error ? err.message : 'Unknown error'}`);
    }

    if (!isValid) {
      throw new SecurityViolationError('Envelope signature verification failed: Payload integrity compromised.');
    }

    return true;
  }
}

/**
 * @fileoverview Foundational domain types and branded identifiers for the fraud detection engine.
 * Implements strict type-safety and immutability for high-throughput financial transaction processing.
 */

/**
 * Nominal typing utility for creating branded primitives.
 * Adds a compile-time-only tag to prevent accidental assignment between different ID types.
 */
export type Branded<T, B> = T & { readonly __brand: B };

/**
 * Branded identifier for system users.
 */
export type UserId = Branded<string, 'UserId'>;

/**
 * Branded identifier for transactions.
 */
export type TransactionId = Branded<string, 'TransactionId'>;

/**
 * Branded identifier for merchants.
 */
export type MerchantId = Branded<string, 'MerchantId'>;

/**
 * Represents financial values using an integer-based 'MinorUnit' pattern to prevent floating-point errors.
 * E.g., USD 10.00 is represented as 1000.
 */
export interface MonetaryAmount {
  readonly value: bigint;
  readonly currency: string;
}

/**
 * Standard metadata for event-sourced domain objects, supporting versioning and security.
 */
export interface EventMetadata {
  readonly schemaVersion: number;
  readonly createdAt: number;
  readonly signature: string;
}

/**
 * Defines an immutable base for domain entities.
 */
export interface DomainEntity {
  readonly metadata: EventMetadata;
}

/**
 * Type guard for UserId.
 */
export const isUserId = (id: string): id is UserId => {
  return typeof id === 'string' && id.length > 0;
};

/**
 * Type guard for TransactionId.
 */
export const isTransactionId = (id: string): id is TransactionId => {
  return typeof id === 'string' && id.length > 0;
};

/**
 * Type guard for MerchantId.
 */
export const isMerchantId = (id: string): id is MerchantId => {
  return typeof id === 'string' && id.length > 0;
};

/**
 * Utility function to safely cast a raw string to a UserId.
 * Use only at the system boundary (e.g., ingress from Kafka/API).
 */
export const asUserId = (id: string): UserId => {
  if (!isUserId(id)) throw new Error('Invalid UserId format');
  return id;
};

/**
 * Utility function to safely cast a raw string to a TransactionId.
 * Use only at the system boundary (e.g., ingress from Kafka/API).
 */
export const asTransactionId = (id: string): TransactionId => {
  if (!isTransactionId(id)) throw new Error('Invalid TransactionId format');
  return id;
};

/**
 * Utility function to safely cast a raw string to a MerchantId.
 * Use only at the system boundary (e.g., ingress from Kafka/API).
 */
export const asMerchantId = (id: string): MerchantId => {
  if (!isMerchantId(id)) throw new Error('Invalid MerchantId format');
  return id;
};

/**
 * Creates a monetary amount object enforcing big integer representation.
 */
export const createMonetaryAmount = (value: bigint | number | string, currency: string): MonetaryAmount => {
  return Object.freeze({
    value: BigInt(value),
    currency,
  });
};

/**
 * @fileoverview Immutable domain model definitions for transaction events.
 * This file contains the structural contracts for the Event Sourced architecture,
 * ensuring type safety, immutability, and performance for high-throughput fraud detection.
 */

import {
  UserId,
  TransactionId,
  MerchantId,
  MonetaryAmount,
  DomainEntity,
} from '../common/domain-types';

/**
 * High-fidelity environmental telemetry for fraud scoring.
 */
export interface Telemetry {
  readonly latitude: number;
  readonly longitude: number;
  readonly deviceFingerprint: string;
  readonly ipAddress: string;
  readonly userAgent: string;
}

/**
 * Base transaction event interface.
 */
export interface TransactionEvent extends DomainEntity {
  readonly transactionId: TransactionId;
  readonly userId: UserId;
  readonly merchantId: MerchantId;
  readonly amount: MonetaryAmount;
  readonly timestamp: bigint;
  readonly telemetry: Telemetry;
}

/**
 * Initial state of a transaction upon ingestion.
 */
export interface TransactionInitiated extends TransactionEvent {
  readonly type: 'TransactionInitiated';
}

/**
 * State after successful cryptographic validation.
 */
export interface TransactionValidated extends TransactionEvent {
  readonly type: 'TransactionValidated';
  readonly validatorId: string;
}

/**
 * Terminal state for flagged fraudulent transactions.
 */
export interface TransactionFlagged extends TransactionEvent {
  readonly type: 'TransactionFlagged';
  readonly reason: string;
  readonly riskScore: number;
}

/**
 * Union type representing all possible transaction event states in the system.
 */
export type Transaction = 
  | TransactionInitiated 
  | TransactionValidated 
  | TransactionFlagged;

/**
 * Type guard for TransactionInitiated.
 */
export const isTransactionInitiated = (event: Transaction): event is TransactionInitiated =>
  event.type === 'TransactionInitiated';

/**
 * Type guard for TransactionValidated.
 */
export const isTransactionValidated = (event: Transaction): event is TransactionValidated =>
  event.type === 'TransactionValidated';

/**
 * Type guard for TransactionFlagged.
 */
export const isTransactionFlagged = (event: Transaction): event is TransactionFlagged =>
  event.type === 'TransactionFlagged';
